	:param n: the input number
	:return: the largest digit in the number
	"""
def find_largest_digit(n: Any) -> object {
    if (n < 0) {
        m = n * -1;
        return find_largest_digit(m);
    } elif (n < 10) {
        n = int(n);
        return n;
    } elif (((n % 100) > 0) and ((n % 10) > 0)) {
        if (((n % 10) * 10) >= (n % 100)) {
            m = ((n - (n % 100)) / 10) + (n % 10);
            return find_largest_digit(m);
        } else {
            m = (n - (n % 10)) / 10;
            return find_largest_digit(m);
        }
    }
}

